// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { cn } from "@/lib/utils";



/* ------------------------------------------------------------------ */
/* Types                                                               */
/* ------------------------------------------------------------------ */

export interface CommandMenuItem {
  id: string;
  label: string;
  /** Items with the same group name are listed under one heading. */
  group: string;
  icon?: React.ReactNode;
  description?: string;
  /** Keys shown as badges, e.g. ["⌘", "S"]. */
  shortcut?: string[];
  /** Extra search terms that are not visible in the label. */
  keywords?: string[];
  onSelect?: () => void;
}

export interface CommandMenuProps {
  isOpen: boolean;
  onClose: () => void;
  items: CommandMenuItem[];
  /** Fired for every selected item (after the item's own onSelect). */
  onSelect?: (item: CommandMenuItem) => void;
  /** When provided, typing adds an "Ask AI" row at the top of the results. */
  onAskAI?: (query: string) => void;
  placeholder?: string;
  emptyMessage?: string;
  closeOnSelect?: boolean;
  className?: string;
}

const ASK_AI_ID = "__ask-ai__";



/* ------------------------------------------------------------------ */
/* Inline icons (no icon library needed)                               */
/* ------------------------------------------------------------------ */

function SvgIcon({ d, className }: { d: string; className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className} aria-hidden="true">
      <path d={d} />
    </svg>
  );
}

export const SearchIcon = ({ className }: { className?: string }) => (
  <SvgIcon className={className} d="M11 19a8 8 0 100-16 8 8 0 000 16z M21 21l-4.3-4.3" />
);
export const SparklesIcon = ({ className }: { className?: string }) => (
  <SvgIcon className={className} d="M12 3l1.9 5.1L19 10l-5.1 1.9L12 17l-1.9-5.1L5 10l5.1-1.9L12 3z M19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8z" />
);



/* ------------------------------------------------------------------ */
/* Shortcut hook: Cmd+K on macOS, Ctrl+K elsewhere                     */
/* ------------------------------------------------------------------ */

export function useCommandShortcut(onTrigger: () => void, key = "k") {
  const callback = React.useRef(onTrigger);
  callback.current = onTrigger;

  React.useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === key) {
        e.preventDefault();
        callback.current();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [key]);
}



/* ------------------------------------------------------------------ */
/* Search helpers                                                      */
/* ------------------------------------------------------------------ */

// True when the letters of q appear in order inside text ("sth" matches "settings")
const isSubsequence = (text: string, q: string) => {
  let i = 0;
  for (const ch of text) {
    if (ch === q[i]) i++;
    if (i === q.length) return true;
  }
  return false;
};

// Higher is better, 0 means no match
function score(item: CommandMenuItem, q: string) {
  const label = item.label.toLowerCase();
  if (label.startsWith(q)) return 4;
  if (label.includes(q)) return 3;
  if (item.keywords?.some((k) => k.toLowerCase().includes(q))) return 2;
  if (`${item.description ?? ""} ${item.group}`.toLowerCase().includes(q)) return 1;
  return isSubsequence(label, q) ? 1 : 0;
}

export function Kbd({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <kbd className={cn("inline-flex h-5 min-w-5 items-center justify-center rounded border border-border bg-muted px-1.5 font-sans text-[10px] font-medium text-muted-foreground", className)}>
      {children}
    </kbd>
  );
}



/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

export function CommandMenu({
  isOpen,
  onClose,
  items,
  onSelect,
  onAskAI,
  placeholder = "Search commands or ask AI…",
  emptyMessage = "No results found.",
  closeOnSelect = true,
  className,
}: CommandMenuProps) {
  const listId = React.useId();
  const listRef = React.useRef<HTMLDivElement>(null);
  const previousFocus = React.useRef<HTMLElement | null>(null);
  const [mounted, setMounted] = React.useState(false);
  const [render, setRender] = React.useState(isOpen); // keeps the menu in the DOM while it animates out
  const [shown, setShown] = React.useState(false);    // drives the enter / exit transition
  const [query, setQuery] = React.useState("");
  const [active, setActive] = React.useState(0);

  React.useEffect(() => setMounted(true), []);

  // Enter: mount first, then flip `shown` so the CSS transition runs. Exit: reverse it, then unmount
  React.useEffect(() => {
    if (isOpen) {
      setRender(true);
      const id = window.setTimeout(() => setShown(true), 10);
      return () => window.clearTimeout(id);
    }
    setShown(false);
    const id = window.setTimeout(() => setRender(false), 200);
    return () => window.clearTimeout(id);
  }, [isOpen]);

  // Fresh state every time the menu opens
  React.useEffect(() => {
    if (isOpen) setQuery("");
  }, [isOpen]);
  React.useEffect(() => setActive(0), [query, isOpen]);

  // Lock page scroll while open and hand focus back to whatever opened the menu
  React.useEffect(() => {
    if (!isOpen) return;
    previousFocus.current = document.activeElement as HTMLElement | null;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = prevOverflow;
      previousFocus.current?.focus?.();
    };
  }, [isOpen]);

  // Filter, rank and group the items
  const groups = React.useMemo(() => {
    const q = query.trim().toLowerCase();
    const scored = items
      .map((item) => ({ item, s: q ? score(item, q) : 1 }))
      .filter((row) => row.s > 0);

    const byGroup = new Map<string, typeof scored>();
    for (const row of scored) {
      const list = byGroup.get(row.item.group) ?? [];
      list.push(row);
      byGroup.set(row.item.group, list);
    }

    const result = [...byGroup].map(([name, rows]) => ({
      name,
      items: (q ? [...rows].sort((a, b) => b.s - a.s) : rows).map((r) => r.item),
    }));

    // "Ask AI" always comes first while typing
    if (onAskAI && q) {
      result.unshift({
        name: "AI",
        items: [{ id: ASK_AI_ID, group: "AI", label: `Ask AI: “${query.trim()}”`, icon: <SparklesIcon />, description: "Send this as a prompt" }],
      });
    }
    return result;
  }, [items, query, onAskAI]);

  const flat = React.useMemo(() => groups.flatMap((g) => g.items), [groups]);
  const activeIndex = Math.min(active, Math.max(flat.length - 1, 0));

  // Keep the highlighted row visible while using the arrow keys
  React.useEffect(() => {
    if (!isOpen) return;
    listRef.current?.querySelector<HTMLElement>(`[data-index="${activeIndex}"]`)?.scrollIntoView?.({ block: "nearest" });
  }, [activeIndex, isOpen]);

  const choose = (item: CommandMenuItem) => {
    if (item.id === ASK_AI_ID) onAskAI?.(query.trim());
    else {
      item.onSelect?.();
      onSelect?.(item);
    }
    if (closeOnSelect) onClose();
  };

  // Keyboard handling for the whole dialog (focus stays in the input)
  const handleKeyDown = (e: React.KeyboardEvent) => {
    const count = flat.length;
    switch (e.key) {
      case "ArrowDown": e.preventDefault(); setActive(count ? (activeIndex + 1) % count : 0); break;
      case "ArrowUp": e.preventDefault(); setActive(count ? (activeIndex - 1 + count) % count : 0); break;
      case "Home": e.preventDefault(); setActive(0); break;
      case "End": e.preventDefault(); setActive(Math.max(count - 1, 0)); break;
      case "Enter": {
        if (e.nativeEvent.isComposing) break;
        e.preventDefault();
        const item = flat[activeIndex];
        if (item) choose(item);
        break;
      }
      case "Escape": e.preventDefault(); onClose(); break;
      case "Tab": e.preventDefault(); break; // keep focus inside the dialog
    }
  };

  if (!mounted || !render) return null;

  let rowIndex = -1; // running index across all groups

  return createPortal(
    <div className={cn("fixed inset-0 z-[100] flex items-start justify-center px-4 pt-[12vh] sm:pt-[15vh]", !shown && "pointer-events-none")}>
      {/* Blurred backdrop */}
      <div
        aria-hidden="true"
        onClick={onClose}
        className={cn(
          "absolute inset-0 bg-background/70 backdrop-blur-md transition-opacity duration-200 motion-reduce:transition-none",
          shown ? "opacity-100" : "opacity-0"
        )}
      />

      {/* Panel: scales in on open, fades out on close */}
      <div
        role="dialog"
        aria-modal="true"
        aria-label="Command menu"
        onKeyDown={handleKeyDown}
        className={cn(
          "relative w-full max-w-xl overflow-hidden rounded-2xl border border-border bg-popover text-popover-foreground",
          "shadow-2xl shadow-black/20 dark:shadow-black/60",
          "transition-all duration-200 ease-out motion-reduce:transform-none motion-reduce:transition-none",
          shown ? "translate-y-0 scale-100 opacity-100" : "-translate-y-2 scale-95 opacity-0",
          className
        )}
      >
        {/* Search field */}
        <div className="flex items-center gap-3 border-b border-border px-4">
          <SearchIcon className="size-4 shrink-0 text-muted-foreground" />
          <input
            autoFocus
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={placeholder}
            role="combobox"
            aria-expanded="true"
            aria-controls={listId}
            aria-activedescendant={flat[activeIndex] ? `${listId}-${activeIndex}` : undefined}
            aria-label={placeholder}
            className="h-14 w-full bg-transparent text-[15px] text-foreground outline-none placeholder:text-muted-foreground"
          />
          <Kbd>esc</Kbd>
        </div>

        {/* Results. Mouse-down is cancelled so the input never loses focus */}
        <div
          ref={listRef}
          id={listId}
          role="listbox"
          onMouseDown={(e) => e.preventDefault()}
          className="max-h-[min(60vh,380px)] overflow-y-auto overscroll-contain p-2"
        >
          {flat.length === 0 && <p className="px-3 py-10 text-center text-sm text-muted-foreground">{emptyMessage}</p>}

          {groups.map((group, gi) => (
            <div key={group.name} role="group" aria-labelledby={`${listId}-g${gi}`} className="[&:not(:first-child)]:mt-1">
              <div id={`${listId}-g${gi}`} className="px-3 pb-1 pt-2 text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
                {group.name}
              </div>

              {group.items.map((item) => {
                const index = ++rowIndex;
                const isActive = index === activeIndex;
                return (
                  <div
                    key={item.id}
                    id={`${listId}-${index}`}
                    role="option"
                    aria-selected={isActive}
                    data-index={index}
                    onMouseMove={() => setActive(index)}
                    onClick={() => choose(item)}
                    className={cn(
                      "flex cursor-pointer items-center gap-3 rounded-xl px-3 py-2 text-sm transition-colors",
                      isActive ? "bg-accent text-accent-foreground" : "text-foreground"
                    )}
                  >
                    {item.icon && (
                      <span className={cn("grid size-8 shrink-0 place-items-center rounded-lg border border-border bg-background text-muted-foreground [&_svg]:size-4", isActive && "text-foreground")}>
                        {item.icon}
                      </span>
                    )}
                    <span className="min-w-0 flex-1">
                      <span className="block truncate font-medium">{item.label}</span>
                      {item.description && <span className="block truncate text-xs text-muted-foreground">{item.description}</span>}
                    </span>
                    {item.shortcut ? (
                      <span className="flex shrink-0 gap-1">{item.shortcut.map((k) => <Kbd key={k}>{k}</Kbd>)}</span>
                    ) : (
                      isActive && <Kbd>↵</Kbd>
                    )}
                  </div>
                );
              })}
            </div>
          ))}
        </div>

        {/* Footer hints */}
        <div className="hidden items-center gap-4 border-t border-border px-4 py-2.5 text-xs text-muted-foreground sm:flex">
          <span className="flex items-center gap-1.5"><Kbd>↑</Kbd><Kbd>↓</Kbd>Navigate</span>
          <span className="flex items-center gap-1.5"><Kbd>↵</Kbd>Select</span>
          <span className="ml-auto flex items-center gap-1.5"><Kbd>esc</Kbd>Close</span>
        </div>
      </div>
    </div>,
    document.body
  );
}

